<script setup lang="ts">
import { computed, nextTick, ref } from 'vue'
import { ArrowDown, ArrowLeft, ArrowRight, Check, ChevronRight, CircleHelp, Code2, Eye, ListChecks, Play, Search, ShieldCheck, Terminal, Workflow } from 'lucide-vue-next'
import CopyButton from './components/CopyButton.vue'
import type { ToolDoc, ToolInspector } from '../services/webmcp/documentation'
import { promptLibrary, workflows, type ToolWorkflow } from './webmcp-content'

const props = defineProps<{
  tools: ToolDoc[]
  inspector: ToolInspector
  runSafe: (name: string, args: Record<string, unknown>) => Promise<unknown>
}>()

const query = ref('')
const selectedCategory = ref('All prompts')
const selectedWorkflowId = ref(workflows[0]!.id)
const selectedStepIndex = ref(0)
const comparisonStage = ref(-1)
const comparisonBusy = ref(false)
const comparisonCalls = ref(0)
const comparisonElapsed = ref<number | null>(null)
const comparisonResult = ref<unknown>(undefined)
const comparisonError = ref('')
const toolBusy = ref('')
const toolResults = ref<Record<string, { result?: unknown; error?: string }>>({})
const previewTool = ref<ToolDoc | null>(null)
const previewDialog = ref<HTMLDialogElement | null>(null)

const visibleTools = computed(() => {
  const term = query.value.trim().toLowerCase()
  return props.tools.filter(tool => !term || [tool.name, tool.title, tool.description, tool.classification].some(value => value.toLowerCase().includes(term)))
})
const categories = ['All prompts', ...new Set(promptLibrary.map(prompt => prompt.category))]
const visiblePrompts = computed(() => promptLibrary.filter(prompt => selectedCategory.value === 'All prompts' || prompt.category === selectedCategory.value))
const currentWorkflow = computed(() => workflows.find(workflow => workflow.id === selectedWorkflowId.value) ?? workflows[0]!)
const currentStep = computed(() => currentWorkflow.value.steps[selectedStepIndex.value] ?? currentWorkflow.value.steps[0]!)
const oldSteps = [
  { title: 'Inspect the Control screen', detail: 'Read the selected capture source and target from the current layout.' },
  { title: 'Find task and queue controls', detail: 'Locate their cards and inspect their current status labels.' },
  { title: 'Reinspect and summarize', detail: 'Check that the screen still shows the same task before answering.' },
]
const comparisonStatus = computed(() => {
  const value = comparisonResult.value
  if (!value || typeof value !== 'object') return ''
  const status = value as Record<string, unknown>
  const target = status.target as { type?: string; id?: string } | undefined
  const task = status.task as { state?: string } | undefined
  return `${target ? `${target.type ?? 'target'} · ${target.id ?? 'unselected'}` : 'No selected target'}. Task ${task?.state ?? 'not started'}. Bridge ${status.paired ? 'paired' : 'not paired'}.`
})

type Schema = Record<string, unknown>
function format(value: unknown) { return JSON.stringify(value, null, 2) ?? 'No result yet.' }
function liveFormat(value: unknown) {
  return JSON.stringify(value, (key, item) => {
    if ((key === 'data' || key === 'image') && typeof item === 'string' && item.length > 300) return `[image data omitted from inspector, ${item.length.toLocaleString()} characters]`
    return item
  }, 2) ?? 'No result yet.'
}
function schemaVariants(schema: Schema): { label: string; schema: Schema }[] {
  const variants = (schema.oneOf ?? schema.anyOf) as Schema[] | undefined
  if (!variants?.length) return [{ label: 'Arguments', schema }]
  return variants.map((variant, index) => {
    const properties = variant.properties as Record<string, Schema> | undefined
    const discriminator = properties?.type ?? properties?.operation
    return { label: String(discriminator?.const ?? (Array.isArray(discriminator?.enum) && discriminator.enum.length === 1 ? discriminator.enum[0] : `Variant ${index + 1}`)), schema: variant }
  })
}
function schemaFields(schema: Schema) {
  const required = Array.isArray(schema.required) ? schema.required : []
  return Object.entries((schema.properties ?? {}) as Record<string, Schema>).map(([name, property]) => ({
    name,
    required: required.includes(name),
    type: property.const !== undefined ? JSON.stringify(property.const) : Array.isArray(property.enum) ? property.enum.map(value => JSON.stringify(value)).join(' | ') : String(property.type ?? (property.oneOf ? 'one of the declared variants' : 'see schema')),
    description: typeof property.description === 'string' ? property.description : '',
  }))
}
function resultError(result: unknown): string {
  if (result && typeof result === 'object' && 'isError' in result && result.isError) return 'The tool returned an error. Read the structured result below.'
  return ''
}
async function runComparison() {
  comparisonBusy.value = true
  comparisonError.value = ''
  comparisonResult.value = undefined
  comparisonCalls.value += 1
  const started = performance.now()
  try {
    const result = await props.runSafe('desktop_status', {})
    comparisonResult.value = result
    comparisonError.value = resultError(result)
  } catch (reason) { comparisonError.value = reason instanceof Error ? reason.message : String(reason) }
  finally { comparisonElapsed.value = Math.round(performance.now() - started); comparisonBusy.value = false }
}
async function runTool(tool: ToolDoc) {
  if (!tool.safeRun) { await openPreview(tool); return }
  toolBusy.value = tool.name
  try {
    const result = await props.runSafe(tool.name, tool.exampleArguments)
    toolResults.value[tool.name] = { result, error: resultError(result) }
  } catch (reason) { toolResults.value[tool.name] = { error: reason instanceof Error ? reason.message : String(reason) } }
  finally { toolBusy.value = '' }
}
async function openPreview(tool: ToolDoc) {
  previewTool.value = tool
  await nextTick()
  previewDialog.value?.showModal()
}
function closePreview() { previewDialog.value?.close(); previewTool.value = null }
function selectWorkflow(workflow: ToolWorkflow) { selectedWorkflowId.value = workflow.id; selectedStepIndex.value = 0 }
async function jumpToTool(event: MouseEvent, name: string) {
  if (event.metaKey || event.ctrlKey || event.shiftKey || event.altKey || event.button !== 0) return
  event.preventDefault()
  query.value = ''
  await nextTick()
  const target = document.getElementById(`tool-${name}`)
  location.hash = `tool-${name}`
  target?.focus({ preventScroll: true })
  target?.scrollIntoView({ block: 'start' })
}
function structuredWorkflow(workflow: ToolWorkflow) {
  return { name: workflow.name, execution: 'documentation preview only', steps: workflow.steps.map(({ tool, args, uses, expectedState }) => ({ tool, args, uses, expectedState })) }
}
</script>

<template>
  <div class="webmcp-page">
    <a class="docs-skip" href="#tool-catalog">Skip to the tool catalog</a>
    <header class="docs-hero">
      <div class="docs-hero-copy">
        <p class="docs-kicker"><span class="docs-kicker-dot"></span> Lense / WebMCP documentation</p>
        <h1>One application.<br><em>Two ways to work.</em></h1>
        <p class="docs-lead">Choose a screen, follow a task, and inspect the evidence. People use Lense's controls. Agents call the same application through declared tools.</p>
        <div class="docs-hero-actions">
          <a class="docs-button docs-button-primary" href="#tool-catalog">Explore {{ tools.length }} tools <ArrowDown :size="16" /></a>
          <a class="docs-button" href="/">Open Control <ArrowRight :size="16" /></a>
        </div>
        <p class="docs-source-note">Tool cards come from the registered definitions, including their current schemas.</p>
      </div>
      <div class="shared-state-diagram" aria-label="A person using the interface and an agent using WebMCP both use Lense's shared state">
        <div class="diagram-input"><span>Person</span><strong>Visible controls</strong><small>Choose · review · stop</small></div>
        <div class="diagram-input"><span>Agent</span><strong>WebMCP tools</strong><small>Observe · act · verify</small></div>
        <div class="diagram-join" aria-hidden="true"><span></span><ArrowDown :size="22" /><span></span></div>
        <div class="diagram-state"><ListChecks :size="22" /><div><strong>The same Lense state</strong><span>Target, task, queue, and evidence</span></div><span class="diagram-status">Live</span></div>
        <p>Vue renders the state. Pinia owns it. Tool calls return structured results.</p>
      </div>
    </header>

    <nav class="docs-section-nav" aria-label="WebMCP documentation sections">
      <a href="#webmcp-introduction">How it works</a><a href="#workflow-comparison">Compare workflows</a><a href="#tool-catalog">Tool catalog <span>{{ tools.length }}</span></a><a href="#prompt-library">Prompts</a><a href="#chained-workflows">Chains</a><a href="#live-inspector">Live inspector</a>
    </nav>

    <section id="webmcp-introduction" class="docs-section" aria-labelledby="introduction-title">
      <div class="docs-section-heading"><span class="docs-section-number">01</span><div><p class="docs-kicker">A browser contract for the agent</p><h2 id="introduction-title">Read the tools. Work with the application.</h2></div></div>
      <p class="docs-section-intro">WebMCP lets a browser application declare named tools, describe their arguments with JSON Schema, and return results an agent can inspect. In Lense, the tools connect directly to capture, input, task management, and the OSRS reference library.</p>
      <div class="docs-two-column intro-cards">
        <article class="docs-card"><span class="docs-card-label">Through the interface</span><h3>You choose the scope of the work.</h3><p>Select a native monitor or window, or share a browser screen. Set a task and its limits, inspect screenshots and action receipts, and use Pause or Stop when you need control back.</p><a href="/" class="docs-text-link">Open the controls <ArrowRight :size="16" /></a></article>
        <article class="docs-card"><span class="docs-card-label">Through WebMCP</span><h3>The agent works with typed requests.</h3><p>Read the selected target, capture a frame, submit an input action, manage a queue, or look up a reference. Those calls use the same stores and services as the controls, so their effects appear in the interface.</p><a href="#chained-workflows" class="docs-text-link">Follow a complete chain <ArrowRight :size="16" /></a></article>
      </div>
      <div class="docs-boundary"><ShieldCheck :size="23" /><div><strong>Desktop access starts with a person.</strong><p>Pairing requires the visible Pair button and the Windows permission prompt. Native input stays within the approved session. Browser sharing is observation-only. Stop revokes native access. The examples on this page execute only allowlisted read-only calls; other calls open a preview.</p></div></div>
    </section>

    <section id="workflow-comparison" class="docs-section" aria-labelledby="comparison-title">
      <div class="docs-section-heading"><span class="docs-section-number">02</span><div><p class="docs-kicker">From screen interpretation to declared intent</p><h2 id="comparison-title">Fewer guesses between a goal and a result.</h2></div></div>
      <div class="comparison-grid">
        <article class="comparison-card comparison-old"><div class="comparison-card-heading"><Eye :size="22" /><h3>The screen-first approach</h3></div><ol><li>Inspect a screenshot or DOM.</li><li>Infer what each control means.</li><li>Find and manipulate UI elements.</li><li>Reinspect the interface after an action.</li><li>Repair the interaction when the layout changes.</li></ol><p>Useful when an application has no declared tools. The agent must interpret both the interface and the task.</p></article>
        <article class="comparison-card comparison-new"><div class="comparison-card-heading"><Code2 :size="22" /><h3>The WebMCP approach</h3></div><ol><li>Discover the registered tools.</li><li>Read names, descriptions, and schemas.</li><li>Submit structured arguments.</li><li>Inspect the structured result.</li><li>Keep the call when presentation changes.</li></ol><p>Lense gives the agent a stable way to request work. Desktop screenshots still provide evidence for visual decisions.</p></article>
      </div>
      <div class="comparison-demo docs-card">
        <div class="comparison-demo-heading"><div><p class="docs-kicker">Try the same goal both ways</p><h3>"Which target is selected, and is my task running?"</h3></div><span class="docs-pill">Read-only example</span></div>
        <div class="comparison-demo-paths">
          <div class="comparison-path">
            <div class="comparison-path-label"><strong>UI walkthrough</strong><span>Illustrative</span></div>
            <ol class="walkthrough-steps"><li v-for="(step, index) in oldSteps" :key="step.title" :class="{ reached: comparisonStage >= index, current: comparisonStage === index }"><span>{{ index + 1 }}</span><div><strong>{{ step.title }}</strong><p v-if="comparisonStage === index">{{ step.detail }}</p></div></li></ol>
            <button class="docs-button" @click="comparisonStage = comparisonStage >= oldSteps.length - 1 ? 0 : comparisonStage + 1">{{ comparisonStage < 0 ? 'Walk through the example' : comparisonStage === oldSteps.length - 1 ? 'Replay walkthrough' : 'Show next step' }} <ChevronRight :size="16" /></button>
            <dl class="comparison-metrics"><div><dt>Screen observations</dt><dd>{{ Math.max(0, comparisonStage + 1) }}</dd></div><div><dt>Agent UI operations</dt><dd>0</dd></div><div><dt>Tool calls</dt><dd>0</dd></div></dl>
            <p class="comparison-demo-note" aria-live="polite">{{ comparisonStage === oldSteps.length - 1 ? 'Illustration complete. ' : '' }}An illustrated reading sequence, not a benchmark or an automated run. This goal requires no UI changes.</p>
          </div>
          <div class="comparison-path comparison-live">
            <div class="comparison-path-label"><strong>Structured call</strong><span>Measured in this session</span></div>
            <div class="comparison-call"><Terminal :size="18" /><code>desktop_status({})</code></div>
            <p>Read target, pairing, current task, and queue from the application's current state in one call.</p>
            <button class="docs-button docs-button-primary" :disabled="comparisonBusy || !!toolBusy" @click="runComparison"><Play :size="15" />{{ comparisonBusy ? 'Reading current status…' : 'Run live status check' }}</button>
            <dl class="comparison-metrics"><div><dt>Screen observations</dt><dd>0</dd></div><div><dt>Agent UI operations</dt><dd>0</dd></div><div><dt>Tool calls</dt><dd>{{ comparisonCalls }}</dd></div></dl>
            <p class="comparison-demo-note">{{ comparisonElapsed === null ? 'No call has run yet. Counts reset when you leave this page.' : `Last call returned in ${comparisonElapsed} ms. Call count is cumulative for this page visit.` }}</p>
          </div>
        </div>
        <div v-if="comparisonResult !== undefined || comparisonError" class="comparison-outcome" :class="{ 'docs-error': comparisonError }" role="status"><Check v-if="!comparisonError" :size="18" /><div><strong>{{ comparisonError ? 'Status check needs attention' : 'Current state returned' }}</strong><p>{{ comparisonError || comparisonStatus }}</p><details v-if="comparisonResult !== undefined"><summary>Inspect the measured result</summary><pre><code>{{ liveFormat(comparisonResult) }}</code></pre></details></div></div>
      </div>
    </section>

    <section id="tool-catalog" class="docs-section" aria-labelledby="catalog-title">
      <div class="docs-section-heading"><span class="docs-section-number">03</span><div><p class="docs-kicker">From the registered tool definitions</p><h2 id="catalog-title">The complete tool catalog.</h2></div><span class="docs-pill">{{ tools.length }} registered tools</span></div>
      <div class="catalog-search-row"><p>Every tool has a schema, example, and recovery path. Read the operation before you run it.</p><label class="catalog-search"><Search :size="18" /><span class="sr-only">Search tools</span><input v-model="query" type="search" placeholder="Search tools or purpose" /></label></div>
      <p class="catalog-count" aria-live="polite">Showing {{ visibleTools.length }} of {{ tools.length }} tools</p>
      <div class="tool-catalog-list">
        <article v-for="tool in visibleTools" :id="`tool-${tool.name}`" :key="tool.name" class="tool-card" :data-tool-name="tool.name" tabindex="-1">
          <div class="tool-card-header"><div><code class="tool-name">{{ tool.name }}</code><h3>{{ tool.title }}</h3></div><span class="tool-classification" :class="{ 'tool-read-only': tool.classification === 'read-only' }">{{ tool.classification }}</span></div>
          <p class="tool-purpose">{{ tool.description }}</p>
          <div class="tool-example-prompt"><p>{{ tool.prompt }}</p><CopyButton :text="tool.prompt" label="Copy prompt" /></div>
          <div class="tool-card-actions"><CopyButton :text="format(tool.exampleArguments)" label="Copy arguments" /><CopyButton :text="tool.name" label="Copy tool name" /><button class="docs-button docs-button-small" :class="{ 'docs-button-primary': tool.safeRun }" :disabled="!!toolBusy || comparisonBusy" @click="runTool(tool)"><Play v-if="tool.safeRun" :size="14" /><Eye v-else :size="15" />{{ toolBusy === tool.name ? 'Reading…' : tool.safeRun ? 'Run read-only example' : 'Preview call' }}</button></div>
          <div class="tool-doc-details">
            <details class="tool-disclosure"><summary>Arguments and JSON Schema <span>{{ schemaVariants(tool.inputSchema).length > 1 ? `${schemaVariants(tool.inputSchema).length} variants` : `${schemaFields(tool.inputSchema).length} properties` }}</span></summary><div class="tool-disclosure-body"><h4>Representative valid arguments</h4><pre><code>{{ format(tool.exampleArguments) }}</code></pre><div v-for="variant in schemaVariants(tool.inputSchema)" :key="variant.label" class="parameter-variant"><h4>{{ variant.label }}</h4><p v-if="!schemaFields(variant.schema).length">No input properties. Pass an empty object.</p><dl v-else class="parameter-list"><div v-for="field in schemaFields(variant.schema)" :key="field.name"><dt><code>{{ field.name }}</code><span :class="{ required: field.required }">{{ field.required ? 'Required' : 'Optional' }}</span></dt><dd><code>{{ field.type }}</code><p v-if="field.description">{{ field.description }}</p></dd></div></dl></div><details class="raw-schema"><summary>View complete JSON Schema</summary><pre><code>{{ format(tool.inputSchema) }}</code></pre></details></div></details>
            <details class="tool-disclosure"><summary>Result and recovery <span>{{ tool.errors.length }} expected errors</span></summary><div class="tool-disclosure-body"><h4>Representative structured result</h4><p class="docs-example-note">Example data illustrates the result shape. It is not a live session report.</p><pre><code>{{ format(tool.exampleResult) }}</code></pre><h4>Errors and what to do next</h4><dl class="error-reference"><div v-for="error in tool.errors" :key="error.code"><dt><code>{{ error.code }}</code></dt><dd>{{ error.recovery }}</dd></div></dl></div></details>
            <details class="tool-disclosure"><summary>State and implementation</summary><div class="tool-disclosure-body"><h4>Application state affected</h4><ul class="state-effects"><li v-for="effect in tool.state" :key="effect">{{ effect }}</li></ul><h4>Registration source</h4><code class="source-file">{{ tool.source }}</code><p class="docs-example-note">The schema and description above are derived from the active tool definition. Supporting examples are maintained beside the documentation model.</p></div></details>
          </div>
          <div v-if="toolResults[tool.name]" class="tool-live-result" :class="{ 'docs-error': toolResults[tool.name]?.error }" role="status"><strong>{{ toolResults[tool.name]?.error ? 'Read-only call returned an error' : 'Read-only call returned' }}</strong><p v-if="toolResults[tool.name]?.error">{{ toolResults[tool.name]?.error }}</p><details v-if="toolResults[tool.name]?.result !== undefined" open><summary>Live structured result</summary><pre><code>{{ liveFormat(toolResults[tool.name]?.result) }}</code></pre></details></div>
        </article>
        <div v-if="!visibleTools.length" class="docs-empty"><Search :size="25" /><h3>No tools match "{{ query }}".</h3><button class="docs-button" @click="query = ''">Show every tool</button></div>
      </div>
    </section>

    <section id="prompt-library" class="docs-section" aria-labelledby="prompts-title">
      <div class="docs-section-heading"><span class="docs-section-number">04</span><div><p class="docs-kicker">Start with what you want to accomplish</p><h2 id="prompts-title">Prompts with a clear next step.</h2></div></div>
      <p class="docs-section-intro">Copy a prompt into your WebMCP-capable agent. It must still inspect the current session and respect the target and task limits. Copying a prompt does not execute it.</p>
      <div class="prompt-filter" aria-label="Filter prompts by goal"><button v-for="category in categories" :key="category" :aria-pressed="selectedCategory === category" :class="{ selected: selectedCategory === category }" @click="selectedCategory = category">{{ category }}</button></div>
      <p class="catalog-count" aria-live="polite">{{ visiblePrompts.length }} {{ visiblePrompts.length === 1 ? 'prompt' : 'prompts' }} · {{ selectedCategory }}</p>
      <div class="prompt-grid"><article v-for="prompt in visiblePrompts" :key="prompt.id" class="prompt-card"><div class="prompt-meta"><span>{{ prompt.category }}</span><span class="docs-pill">{{ prompt.level }}</span></div><h3>{{ prompt.title }}</h3><p>{{ prompt.prompt }}</p><p v-if="prompt.note" class="prompt-note">{{ prompt.note }}</p><div class="prompt-tools"><a v-for="tool in prompt.tools" :key="tool" :href="`#tool-${tool}`" @click="jumpToTool($event, tool)"><code>{{ tool }}</code></a></div><CopyButton :text="prompt.prompt" label="Copy prompt" /></article></div>
    </section>

    <section id="chained-workflows" class="docs-section" aria-labelledby="chains-title">
      <div class="docs-section-heading"><span class="docs-section-number">05</span><div><p class="docs-kicker">Pass evidence between tools</p><h2 id="chains-title">A task is a sequence of checked steps.</h2></div></div>
      <p class="docs-section-intro">These {{ workflows.length }} chains show where a result becomes the next call's input. They are plans to inspect and copy. The page does not run them.</p>
      <div class="workflow-picker" aria-label="Choose a workflow"><button v-for="workflow in workflows" :key="workflow.id" :aria-pressed="currentWorkflow.id === workflow.id" :class="{ selected: currentWorkflow.id === workflow.id }" @click="selectWorkflow(workflow)"><Workflow :size="17" /><span>{{ workflow.name }}</span><ChevronRight :size="16" /></button></div>
      <article class="workflow-card">
        <div class="workflow-heading"><div><span class="docs-pill">{{ currentWorkflow.level }}</span><h3>{{ currentWorkflow.name }}</h3><p>{{ currentWorkflow.goal }}</p></div><CopyButton :text="currentWorkflow.prompt" label="Copy complete prompt" /></div>
        <p class="workflow-prerequisite"><strong>Before you start</strong>{{ currentWorkflow.prerequisites }}</p>
        <div class="workflow-body"><ol class="workflow-stepper" aria-label="Workflow steps"><li v-for="(step, index) in currentWorkflow.steps" :key="`${currentWorkflow.id}-${index}`"><button :aria-current="selectedStepIndex === index ? 'step' : undefined" :class="{ selected: selectedStepIndex === index }" @click="selectedStepIndex = index"><span class="step-number">{{ index + 1 }}</span><span><strong>{{ step.title }}</strong><code>{{ step.tool }}</code></span><ChevronRight :size="16" /></button></li></ol><div class="workflow-step-detail" aria-live="polite"><div class="workflow-step-label">Step {{ selectedStepIndex + 1 }} of {{ currentWorkflow.steps.length }}</div><h4>{{ currentStep.title }}</h4><p>{{ currentStep.detail }}</p><pre><code>{{ format({ tool: currentStep.tool, arguments: currentStep.args }) }}</code></pre><dl><div><dt>Data passed from earlier steps</dt><dd><ul v-if="currentStep.uses.length"><li v-for="binding in currentStep.uses" :key="binding"><code>{{ binding }}</code></li></ul><span v-else>No earlier result is required.</span></dd></div><div><dt>Expected state</dt><dd>{{ currentStep.expectedState }}</dd></div></dl><div class="workflow-step-actions"><button class="docs-button docs-button-small" :disabled="selectedStepIndex === 0" @click="selectedStepIndex--"><ArrowLeft :size="15" /> Previous</button><button class="docs-button docs-button-small" :disabled="selectedStepIndex === currentWorkflow.steps.length - 1" @click="selectedStepIndex++">Next step <ArrowRight :size="15" /></button></div></div></div>
        <div class="workflow-boundaries"><div><ShieldCheck :size="19" /><h4>Approval boundary</h4><p>{{ currentWorkflow.approval }}</p></div><div><CircleHelp :size="19" /><h4>If a step fails</h4><p>{{ currentWorkflow.partialFailure }}</p></div></div>
        <details class="workflow-structured"><summary>View the complete structured chain</summary><p>Strings such as current-task-id and fresh-native-frame-id mark result bindings. Replace them with current returned values. This preview never executes.</p><pre><code>{{ format(structuredWorkflow(currentWorkflow)) }}</code></pre><CopyButton :text="format(structuredWorkflow(currentWorkflow))" label="Copy structured chain" /></details>
      </article>
    </section>

    <section id="live-inspector" class="docs-section" aria-labelledby="inspector-title">
      <div class="docs-section-heading"><span class="docs-section-number">06</span><div><p class="docs-kicker">Current browser session</p><h2 id="inspector-title">See the contract the agent sees.</h2></div></div>
      <div class="inspector-card">
        <div class="inspector-summary"><div><span>WebMCP availability</span><strong>{{ inspector.availability }}</strong></div><div><span>Registered tools</span><strong>{{ inspector.names.length }}</strong></div><div><span>Schema validation</span><strong>{{ inspector.validation }}</strong><small>Examples checked against registered schemas.</small></div></div>
        <p class="inspector-explainer">{{ inspector.availability.toLowerCase().includes('native') || inspector.availability.toLowerCase().includes('available') && !inspector.availability.toLowerCase().includes('unavailable') ? 'The browser exposes WebMCP registration. These tools remain registered while you navigate between Control, WebMCP, and Hackathon.' : 'This browser does not currently expose native WebMCP registration. The same local tool registry powers this catalog and the allowlisted read-only examples. Open Lense in a WebMCP-capable browser to make the tools available to its agent.' }}</p>
        <div class="inspector-tools"><a v-for="name in inspector.names" :key="name" :href="`#tool-${name}`" @click="jumpToTool($event, name)"><code>{{ name }}</code><ArrowRight :size="13" /></a></div>
        <div class="inspector-recent"><div class="inspector-recent-heading"><h3>Most recent tool call</h3><span v-if="inspector.lastCall">{{ inspector.lastCall.timestamp }}</span></div><template v-if="inspector.lastCall"><code class="inspector-last-name">{{ inspector.lastCall.name }}</code><details><summary>Arguments</summary><pre><code>{{ liveFormat(inspector.lastCall.input) }}</code></pre></details><div v-if="inspector.lastCall.error" class="docs-error inspector-call-error">{{ inspector.lastCall.error }}</div><details v-if="inspector.lastCall.result !== undefined" open><summary>Structured result</summary><pre><code>{{ liveFormat(inspector.lastCall.result) }}</code></pre></details></template><p v-else class="inspector-empty">No tool has run in this session. Try the live status check above to inspect a real response.</p></div>
